head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70020";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.formKey, param.returnKey

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldods70020.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name form_1_onsubmit
 * @description form_1 onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.form_1_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70020.form_1_onsubmit' }); }
};

/**
 * @method
 * @name ipt_selectUrlTp_onclick
 * @description 「Y」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_selectUrlTp_onclick = function(e){
    try {
        scwin.selected()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70020.ipt_selectUrlTp_onclick' }); }
};

/**
 * @method
 * @name ipt_selectUrlTp_2_onclick
 * @description 「N」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_selectUrlTp_2_onclick = function(e){
    try {
        scwin.selected()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70020.ipt_selectUrlTp_2_onclick' }); }
};

/**
 * @method
 * @name btn_input_onclick
 * @description 「입력완료」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_input_onclick = async function(e){
    try {
        await scwin.input()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70020.btn_input_onclick' }); }
};

/**
 * @method
 * @name __on_enter_3_ipt_linkurl
 * @description on enter 3 ipt linkurl 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_3_ipt_linkurl = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await $c.win.alert('입력완료를 클릭하세요.') }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70020.__on_enter_3_ipt_linkURL' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getCheckedValue
 * @description get Checked Value 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getCheckedValue = function (_obj) {
    let checkedValue = '';
    for (let i = 0; i < _obj.getItemCount(); i++) {
        if (_obj[i].checked) {
            checkedValue = _obj[i].value;
            break;
        }
    }
    return checkedValue;
};

/**
 * @method
 * @name selected
 * @description selected 처리
 * @returns {void}
 * @hidden N
 */
scwin.selected = function () {
    const selectUrlTpVal = (String(($c.util.getComponent('ipt_selectUrlTp'))?.getValue?.() ?? "").split(" ")[0] ?? "");
    if (selectUrlTpVal === 'Y') {
        $c.util.getComponent('ipt_linkURL').setDisabled(false);
    } else {
        if (selectUrlTpVal === 'N') {
            $c.util.getComponent("ipt_linkURL").setValue("");
            $c.util.getComponent('ipt_linkURL').setDisabled(true);
        } else {
            $c.util.getComponent('ipt_linkURL').setDisabled(false);
        }
    }
};

/**
 * @method
 * @name input
 * @description input 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.input = async function () {
    const selectUrlTpVal = (String(($c.util.getComponent('ipt_selectUrlTp'))?.getValue?.() ?? "").split(" ")[0] ?? "");
    let selectCode = "";
    let selectName = "";
    if (selectUrlTpVal === 'Y') {
        selectCode = $c.util.getComponent('ipt_linkURL').getValue();
        selectName = $c.util.getComponent('ipt_linkURL').getValue();
        if (selectCode.indexOf("http://") < 0 && selectCode.indexOf("https://") < 0) {
            await $c.win.alert('URL 앞에 http:// 또는 https:// 를 입력해주세요.');
            return;
        }
    } else {
        if (selectUrlTpVal === 'N') {
            $c.util.getComponent("ipt_linkURL").setValue("");
            selectCode = '-';
            selectName = '-';
        } else {
            await $c.win.alert("'Link URL' 또는 '해당없음'을 선택해주세요.");
            return;
        }
    }
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_setSelectedData === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), selectCode, selectName) : void 0), $c.win.closePopup([(String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) == null ? '' : ((dma_pageContext.get("formKey") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) == null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), selectCode, selectName]));
    $c.win.closePopup();
};
